<?php
namespace App\Services;
use App\Models\{AidRequest,Donation,DonationMatch}; use Illuminate\Support\Facades\DB;
class MatchingService { public function run():int{return DB::transaction(function(){ $created=0;Donation::where('status','pending_match')->lockForUpdate()->get()->each(function($donation)use(&$created){$available=$donation->quantity-$this->active($donation->matches());if($available<1)return;$made=false;$requests=AidRequest::where('category',$donation->category)->where('status','approved')->orderByRaw("CASE urgency WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END")->oldest()->lockForUpdate()->get();foreach($requests as $request){if($available<1)break;$remaining=$request->quantity_needed-$this->active($request->matches());if($remaining<1)continue;$qty=min($available,$remaining);$match=DonationMatch::create(['donation_id'=>$donation->id,'request_id'=>$request->id,'matched_quantity'=>$qty]);AlertService::send($request->beneficiary,"A {$qty}-unit {$donation->category} donation has been proposed for your request.",'match','normal',$match,'/matches');AlertService::send($donation->donor,"Your {$qty}-unit donation has been proposed for a verified request.",'match','normal',$match,'/matches');$available-=$qty;$created++;$made=true;$this->refreshStatuses($match);}if(!$made)$this->refreshDonation($donation);});return $created;});} public function refreshStatuses(DonationMatch $m):void{$this->refreshDonation($m->donation);$this->refreshRequest($m->request);} private function active($relation):int{return (int)$relation->whereIn('status',['proposed','confirmed','fulfilled'])->sum('matched_quantity');} private function refreshDonation(Donation $d):void{$m=$d->matches()->whereIn('status',['proposed','confirmed','fulfilled'])->get();$sum=$m->sum('matched_quantity');$s=$sum<$d->quantity?'pending_match':($m->every(fn($x)=>$x->status==='fulfilled')?'fulfilled':($m->contains(fn($x)=>in_array($x->status,['confirmed','fulfilled'],true))?'matched':'proposed'));$d->update(['status'=>$s]);} private function refreshRequest(AidRequest $r):void{$m=$r->matches()->whereIn('status',['proposed','confirmed','fulfilled'])->get();$sum=$m->sum('matched_quantity');$s=$sum<$r->quantity_needed?'approved':($m->every(fn($x)=>$x->status==='fulfilled')?'fulfilled':($m->contains(fn($x)=>in_array($x->status,['confirmed','fulfilled'],true))?'matched':'proposed'));$r->update(['status'=>$s]);} }
